const body = $input.first().json.body || {};
const q=body.question, ctx=body.context_lead_ids;
if (typeof q !== 'string' || q.length<3 || q.length>2000 || /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/u.test(q)) throw new Error('ASK_REQUEST_REJECTED');
if (!Array.isArray(ctx) || ctx.length<1 || ctx.length>20 || new Set(ctx).size!==ctx.length || !ctx.every(x=>typeof x==='string' && /^FAIR-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(x))) throw new Error('ASK_INVALID_CONTEXT');
// Interpret supported intent locally; never send the user's raw question/PII to LLM.
const intents = {score_band:/score|hot|warm|cold|kategorie|bewertung/i,score_total:/score|punkte|bewertung/i,budget_status:/budget/i,training_interest:/training|schulung|interess|kurs/i,follow_up:/follow.?up|nachfass|frist/i,processing_status:/status|verarbeit|process/i,email_status:/e.?mail.?status|versand|zustell/i,duplicate_status:/duplik|duplic/i};
const requested_fields=Object.entries(intents).filter(([,pattern])=>pattern.test(q)).map(([key])=>key);
return [{json:{question:requested_fields.length?'Return these attributes: '+requested_fields.join(', '):'Unsupported request: return unavailable=true and no claims',requested_fields,context_lead_ids:ctx}}];

const payload = $input.first().json.payload;
const wanted = $('Eingabe prüfen').first().json.context_lead_ids;
const fields = ['lead_id','score_band','score_total','processing_status','email_status','duplicate_status','training_interest','budget_status','follow_up'];
if (!payload || payload.success!==true || !Array.isArray(payload.context) || payload.context.length!==wanted.length || new Set(payload.context.map(l=>l.lead_id)).size!==wanted.length || !payload.context.every(l=>wanted.includes(l.lead_id) && Object.keys(l).every(k=>fields.includes(k)))) throw new Error('ASK_CONTEXT_REJECTED');
return [{json:{question:$('Eingabe prüfen').first().json.question,context:payload.context,requested_fields:$('Eingabe prüfen').first().json.requested_fields}}];

const input=$input.first().json, result=input.output ?? input;
const context=$('Kontext filtern').first().json.context;
const requested=$('Kontext filtern').first().json.requested_fields;
const fields=['score_band','score_total','processing_status','email_status','duplicate_status','training_interest','budget_status','follow_up'];
if (!result || typeof result.unavailable!=='boolean' || !Array.isArray(result.claims) || result.claims.length>20) throw new Error('ASK_SCHEMA_INVALID');
const verified=[];
for (const claim of result.claims) {
 const lead=context.find(l=>l.lead_id===claim.lead_id);
 if (!lead || !requested.includes(claim.field) || !fields.includes(claim.field) || !Object.hasOwn(lead,claim.field) || lead[claim.field]!==claim.value) throw new Error('ASK_UNGROUNDED_CLAIM');
 verified.push(claim);
}
const labels={score_band:'Kategorie',score_total:'Score',processing_status:'Verarbeitung',email_status:'E-Mail-Status',duplicate_status:'Duplikatstatus',training_interest:'Trainingsinteresse',budget_status:'Budget',follow_up:'Follow-up'};
const usable=result.unavailable?[]:verified;
// Completeness is distinct *validated* (lead_id, field) coverage, not the claim cap.
// A missing field in scoped context is still missing from the requested answer.
const expected=new Set();
for (const lead of context) for (const field of new Set(requested)) {
 if (fields.includes(field)) expected.add(JSON.stringify([lead.lead_id,field]));
}
const distinct=new Map();
for (const claim of usable) distinct.set(JSON.stringify([claim.lead_id,claim.field]),claim);
const covered=[...distinct.keys()].filter(key=>expected.has(key)).length;
const incomplete=covered<expected.size;
const warning=incomplete ? `⚠ Ergebnis unvollständig (${covered} von ${expected.size} angefragten Werten). Bitte Kontext oder Felder eingrenzen.` : '';
const lines=[...distinct.values()];
const content=lines.length ? lines.map(c=>`${c.lead_id}: ${labels[c.field]} = ${c.value ?? 'unbekannt'}`).join('\n') : 'Dafür habe ich keine Daten im freigegebenen Kontext.';
const answer=warning ? warning+'\n'+content : content;
return [{json:{success:true,answer,cited_lead_ids:[...new Set(lines.map(c=>c.lead_id))]}}];
